template <class T, std::size_t N> class BoundedQueue {
  std::deque<T> q_; std::mutex m_; std::condition_variable notEmpty_, notFull_;
public:
  void push(T v) {
    std::unique_lock lk(m_);
    notFull_.wait(lk, [&]{ return q_.size() < N; });   // the bound
    q_.push_back(std::move(v)); notEmpty_.notify_one(); }
  T pop() {
    std::unique_lock lk(m_);
    notEmpty_.wait(lk, [&]{ return !q_.empty(); });    // waits while empty
    T v = std::move(q_.front()); q_.pop_front(); notFull_.notify_one(); return v; }
};

