template <class T, std::size_t N> class Ring {
  std::array<T, N> buf_; std::size_t r_ = 0, w_ = 0;
  std::counting_semaphore<N> slots_{N}, items_{0};
public:
  void push(T v) { slots_.acquire(); buf_[w_++ % N] = std::move(v); items_.release(); }
  T pop() { items_.acquire(); T v = std::move(buf_[r_++ % N]); slots_.release(); return v; }
};   // single-producer/single-consumer: cursors need no lock
